const body = $input.item.json.body;
const entry = body && body.entry ? body.entry[0] : undefined;
const change = entry && entry.changes ? entry.changes[0] : undefined;
const value = change ? change.value : undefined;

if (!value || !value.messages || value.messages.length === 0) {
  return [{ json: { ignore: true, reason: 'no_message_content' } }];
}

const message = value.messages[0];
const contact = value.contacts ? value.contacts[0] : undefined;
const mediaTypes = ['image', 'document', 'audio', 'video', 'sticker'];

const parsed = {
  ignore: false,
  wa_id: (contact && contact.wa_id) ? contact.wa_id : message.from,
  from: message.from,
  contact_name: (contact && contact.profile) ? contact.profile.name : null,
  message_id: message.id,
  timestamp: message.timestamp,
  type: message.type,
  text: message.text ? message.text.body : null,
  media_id: (mediaTypes.includes(message.type) && message[message.type]) ? message[message.type].id : null,
  media_mime_type: (mediaTypes.includes(message.type) && message[message.type]) ? message[message.type].mime_type : null
};

return [{ json: parsed }];

const body = $input.item.json.body;

if (!body || body.event !== 'messages.upsert' || !body.data) {
  return [{ json: { ignore: true, reason: 'not_a_new_message_event' } }];
}

const data = body.data;
if (!data.key || data.key.fromMe) {
  return [{ json: { ignore: true, reason: 'own_message_or_missing_key' } }];
}

const remoteJid = data.key.remoteJid || '';
const waId = remoteJid.split('@')[0];
const msg = data.message || {};

let type = null, text = null, mediaId = null, mediaMimeType = null;

if (msg.conversation) {
  type = 'text';
  text = msg.conversation;
} else if (msg.extendedTextMessage && msg.extendedTextMessage.text) {
  type = 'text';
  text = msg.extendedTextMessage.text;
} else if (msg.imageMessage) {
  type = 'image';
  text = msg.imageMessage.caption || null;
  mediaMimeType = msg.imageMessage.mimetype || 'image/jpeg';
  mediaId = data.key.id;
} else if (msg.documentMessage) {
  type = 'document';
  text = msg.documentMessage.caption || null;
  mediaMimeType = msg.documentMessage.mimetype || 'application/pdf';
  mediaId = data.key.id;
}

if (!type) {
  return [{ json: { ignore: true, reason: 'unsupported_message_subtype' } }];
}

return [{ json: {
  ignore: false,
  wa_id: waId,
  from: waId,
  contact_name: data.pushName || null,
  message_id: data.key.id,
  timestamp: data.messageTimestamp || null,
  type,
  text,
  media_id: mediaId,
  media_mime_type: mediaMimeType
} }];
